document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('notification-form');
    const statusMessage = document.getElementById('status-message');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        const formData = new FormData(form);
        const preference = formData.get('notification-preference');

        if (preference) {
            statusMessage.textContent = `Success: Your preference for ${preference} has been saved.`;
            statusMessage.className = 'success';

            // In a real app, you'd send this to a server
            console.log('Saved preference:', preference);
        } else {
            statusMessage.textContent = 'Error: Please select a notification preference.';
            statusMessage.className = 'error';
        }
    });
});

